function pairChapter(chapter) { return {title: chapter.title, body: chapter.body}; }

async function runScenario(scenario) {
  const id = randomUUID(), directory = resolve(project, 'runs', `regression-${id}`);
  const database = resolve(directory, 'practice.sqlite'), recordPath = resolve(directory, 'record.json');
  const report = {kind: 'saving_regression_observation', id, scenario, startedAt: now(),
    directory, database, recordPath,
    scope: '完整三章来自既有课堂存档；本次seed为新作品human/draft r1。程序检查不表示文学采用。历史恢复点只用于独立红绿对照；正确工作台在另一个冻结副本。',
    limits: ['每场景一个工作台、一次保存尝试，无布局循环和自动重试。',
      'abort仅发生在服务收到请求前，不覆盖服务提交后断网、撤销或回滚。',
      '未覆盖GET失败、未知终态、并发写入、所有空白字符及页面审美。'],
    environment: {cwd: process.cwd(), project, node: process.version, platform: process.platform,
      arch: process.arch, deliveryBrowserChannel: process.env.DELIVERY_BROWSER_CHANNEL ?? null},
    sources: {}, pages: [], databases: [], service: [], browserNetwork: [], gates: [],
    console: [], dialogs: [], pageErrors: [], assertions: [], completed: [],
    environmentErrors: [], observationErrors: [], recordingErrors: [], cleanupErrors: [], cleanup: [], sourceChanges: []};
  let store, server, browser, context, page, seedModule, input, expectation, A, finalDb;
  const observed = {}, captures = new Set(), routeTasks = new Set();
  const postGate = makeGate('post', report), getGate = makeGate('get', report);
  let postUsed = false, getUsed = false, saveReadArmed = false;
  function persist(label) {
    report.lastCheckpoint = {label, at: now()};
    report.unfinished = planned[scenario].filter(step => !report.completed.includes(step));
    try { writeFileSync(recordPath, JSON.stringify(report, null, 2) + '\n', 'utf8'); }
    catch (error) {
      report.recordingErrors.push({kind: 'write', label, recordPath, error: errorRecord(error)});
      process.stderr.write(`Record write failed: ${recordPath}: ${error.message}\n`);
    }
  }
  async function step(name, action) {
    report.activeStep = name;
    observed[name] = await action();
    report.completed.push(name);
    report.observed = observed;
    persist(name);
    return observed[name];
  }
  async function cleanup(name, action) {
    const entry = {name, startedAt: now()};
    report.cleanup.push(entry);
    try { await bounded(Promise.resolve().then(action), `cleanup/${name}`); entry.completedAt = now(); }
    catch (error) { report.cleanupErrors.push({name, error: errorRecord(error)}); }
  }
  const draftMatch = url => url.pathname === '/api/draft';
  const workMatch = url => url.pathname === '/api/work';
  const trackedRoute = action => route => {
    const job = action(route).catch(error => report.observationErrors.push({step: 'route', error: errorRecord(error)}));
    routeTasks.add(job);
    void job.finally(() => routeTasks.delete(job));
    return job;
  };
  const draftHandler = trackedRoute(async route => {
    if (route.request().method() !== 'POST' || postUsed) { await route.continue(); return; }
    postUsed = true;
    postGate.arrive(route.request());
    if (scenario === 'abort') {
      await route.abort('failed');
      observed.aborted = {at: now(), action: 'route.abort(failed) before service'};
      postGate.entry.abortedAt = now();
      postGate.open('aborted, never continued to service');
    } else {
      await postGate.release.promise;
      saveReadArmed = true;
      postGate.entry.continuedAt = now();
      await route.continue();
    }
  });
  const workHandler = trackedRoute(async route => {
    if (route.request().method() === 'GET' && saveReadArmed && !getUsed) {
      getUsed = true;
      getGate.arrive(route.request());
      await getGate.release.promise;
      getGate.entry.continuedAt = now();
    }
    await route.continue();
  });
  try {
    // No shared practice.json/data path, and no reused database or directory.
    mkdirSync(resolve(project, 'runs'), {recursive: true});
    mkdirSync(directory);
    report.environment.gitBefore = gitState();
    readSources(report);
    input = JSON.parse(report.sources['inputs/完整教师初始化.json'].utf8);
    expectation = JSON.parse(report.sources['inputs/独立业务预期.json'].utf8);
    report.inputs = {initialization: input, expectation};
    const original = input.chapters.find(chapter => chapter.number === expectation.chapterNumber);
    A = plus(pairChapter(original), expectation.edits.before);
    report.independentExpectedA = A;
    persist('inputs');
    const {Store} = await import('../dist/store.js');
    const {prototypeServer} = await import('../dist/prototype-http.js');
    seedModule = await import('./seed.mjs');
    store = new Store(database);
    report.initialization = seedModule.seed(store);
    databaseState(store, seedModule.snapshot, input.work.id, report, 'seed');
    persist('seed');
    const channel = report.environment.deliveryBrowserChannel;
    if (!channel || !channel.trim()) throw new Error('DELIVERY_BROWSER_CHANNEL must explicitly specify the browser channel; no fallback is allowed.');
    if (!/^v24\./.test(process.version) || Number(process.versions.node.split('.')[1]) < 12 ||
      (Number(process.versions.node.split('.')[1]) === 12 && Number(process.versions.node.split('.')[2]) < 0)) {
      throw new Error(`package.json requires Node >=24.12.0 <25; actual ${process.version}`);
    }
    const {chromium} = await import('@playwright/test');
    report.environment.playwright = JSON.parse(readFileSync(resolve(project, 'node_modules/@playwright/test/package.json'), 'utf8')).version;
    browser = await chromium.launch({channel, headless: true, timeout: LIMIT});
    report.environment.browserVersion = browser.version();
    context = await browser.newContext({viewport: {width: 1280, height: 900}});
    page = await context.newPage();
    page.setDefaultTimeout(ACTION_LIMIT);
    page.setDefaultNavigationTimeout(LIMIT);
    instrumentPage(page, report, captures);
    server = prototypeServer(store, input.work.id);
    instrumentServer(server, report);
    await bounded(new Promise((resolveListen, reject) => {
      server.once('error', reject);
      server.listen(0, '127.0.0.1', () => { server.off('error', reject); resolveListen(); });
    }), 'HTTP listen');
    const base = `http://127.0.0.1:${server.address().port}`;
    report.environment.baseURL = base;
    const settled = () => page.waitForFunction(() => {
      const title = document.getElementById('draft-title');
      return document.getElementById('chapters').children.length === 3 &&
        !!title.value && !document.getElementById('reload').disabled;
    }, undefined, {timeout: LIMIT});
    await step('initial', async () => {
      await page.goto(`${base}/?work=${encodeURIComponent(input.work.id)}`);
      await settled();
      return pageState(page, report, 'initial');
    });
    const selectSecond = async () => {
      await page.locator('#chapters button[data-number="2"]').click();
      await page.waitForFunction(() => document.getElementById('chapter-label').textContent.startsWith('第 2 章'),
        undefined, {timeout: LIMIT});
    };
    await step('selected', async () => { await selectSecond(); return pageState(page, report, 'selected'); });
    await step('before', () => attemptPair(page, report, 'before', expectation.edits.before));
    await step('comparison', async () => {
      await page.getByRole('button', {name: '重新读取', exact: true}).click();
      await page.waitForFunction(() => !document.getElementById('comparison').hidden &&
        !document.getElementById('reload').disabled && document.getElementById('message').textContent.includes('已读回'),
        undefined, {timeout: LIMIT});
      return pageState(page, report, 'comparison');
    });
    await step('gatesInstalled', async () => {
      await page.route(draftMatch, draftHandler);
      await page.route(workMatch, workHandler);
      return {at: now(), after: 'initial read, chapter selection, existing comparison', responseMocking: false};
    });
    await page.getByRole('button', {name: '保存草稿', exact: true}).click();
    await bounded(postGate.hit.promise, 'POST gate arrival');
    if (scenario === 'normal') {
      await step('postWait', async () => ({page: await pageState(page, report, 'POST gated'),
        servicePostCount: postRequests(report).length,
        database: databaseState(store, seedModule.snapshot, input.work.id, report, 'POST gated')}));
      await step('postKeyboard', () => attemptPair(page, report, 'post', expectation.edits.post));
      postGate.open('finished POST-wait keyboard observations');
      await bounded(getGate.hit.promise, 'save-read GET gate arrival');
      await step('getWait', async () => ({page: await pageState(page, report, 'GET gated'),
        servicePostCount: postRequests(report).length,
        database: databaseState(store, seedModule.snapshot, input.work.id, report, 'GET gated')}));
      await step('getKeyboard', () => attemptPair(page, report, 'get', expectation.edits.get));
      getGate.open('finished GET-wait keyboard observations');
      await step('readback', async () => {
        await page.waitForFunction(() => !document.getElementById('reload').disabled &&
          document.getElementById('message').textContent.startsWith('已保存'), undefined, {timeout: LIMIT});
        return pageState(page, report, 'readback');
      });
      await step('afterKeyboard', () => attemptPair(page, report, 'after', expectation.edits.after));
      await step('refresh', async () => {
        await page.reload();
        await settled();
        await pageState(page, report, 'refresh before selecting chapter');
        await selectSecond();
        return pageState(page, report, 'refresh second chapter');
      });
    } else {
      await step('aborted', async () => {
        await bounded(postGate.release.promise, 'route abort completion');
        return observed.aborted;
      });
      await step('failureLocal', async () => {
        await page.waitForFunction(() => document.getElementById('message').dataset.kind === 'error' &&
          !document.getElementById('reload').disabled, undefined, {timeout: LIMIT});
        databaseState(store, seedModule.snapshot, input.work.id, report, 'after service-before abort');
        return pageState(page, report, 'abort complete A retained');
      });
      await step('recoveryRead', async () => {
        await page.getByRole('button', {name: '读取当前稿', exact: true}).click();
        await page.waitForFunction(() => !document.getElementById('reload').disabled &&
          document.getElementById('message').textContent.includes('已读回'), undefined, {timeout: LIMIT});
        return pageState(page, report, 'abort read-current restores save permission');
      });
      await step('afterKeyboard', () => attemptPair(page, report, 'abort after', expectation.edits.after));
    }
    await bounded(Promise.all([...captures]), 'complete response recording');
    finalDb = databaseState(store, seedModule.snapshot, input.work.id, report, 'observations complete');
    persist('observations complete; business assertions not yet evaluated');
  } catch (error) {
    report.observationErrors.push({step: report.activeStep ?? 'setup', error: errorRecord(error)});
  } finally {
    // Release both gates even after an observation failure. Cleanup can complete
    // a pending real save; the resulting final database is recorded explicitly.
    postGate.open('finally release');
    getGate.open('finally release');
    if (page) {
      await cleanup('route handlers settle', () => Promise.all([...routeTasks]));
      await cleanup('routes removed', () => page.unrouteAll({behavior: 'wait'}));
      await cleanup('response records drained', () => Promise.all([...captures]));
      await cleanup('page closed without saving local edits', () => page.close({runBeforeUnload: false}));
    }
    if (context) await cleanup('browser context closed', () => context.close());
    if (browser) await cleanup('browser closed', () => browser.close());
    if (server) await cleanup('HTTP closed', () => new Promise((resolveClose, reject) => {
      if (!server.listening) { server.closeAllConnections(); resolveClose(); return; }
      server.close(error => error ? reject(error) : resolveClose());
      server.closeAllConnections();
    }));
    if (store) {
      await cleanup('final five tables and history captured', () => {
        finalDb = databaseState(store, seedModule.snapshot, input.work.id, report, 'after cleanup before Store close');
      });
      await cleanup('Store closed', () => store.close());
    }
    await cleanup('response records final drain', () => Promise.all([...captures]));
    for (const [path, source] of Object.entries(report.sources)) {
      if (source.error) continue;
      try {
        const actual = sha256(readFileSync(resolve(project, path)));
        if (actual !== source.sha256) report.sourceChanges.push({path, before: source.sha256, after: actual});
      } catch (error) { report.recordingErrors.push({kind: 'source reread', path, error: errorRecord(error)}); }
    }
    report.environment.gitAfter = gitState();
    report.observed = observed;
    report.unfinished = planned[scenario].filter(step => !report.completed.includes(step));
    try { assertBusiness(report, observed, input, expectation, A, finalDb); }
    catch (error) { report.assertions.push({name: 'assertion collection completed', passed: false, error: errorRecord(error)}); }
    report.finishedAt = now();
    report.passed = report.assertions.every(item => item.passed) &&
      !report.observationErrors.length && !report.environmentErrors.length &&
      !report.recordingErrors.length && !report.cleanupErrors.length;
    persist('final');
    if (report.recordingErrors.length) report.passed = false;
    process.stdout.write(`${scenario}: ${report.passed ? 'PASS' : 'FAIL'}; record ${recordPath}\n`);
  }
  const failures = report.assertions.filter(item => !item.passed).map(item => item.name);
  assert.equal(report.passed, true, `${scenario} failed: ${failures.join('; ')}; full record: ${recordPath}`);
}

// Sequential, independent node:test cases. A historical normal failure must not
// prevent the service-before abort observation from running with its own seed.
await test('正常保存：完整A、POST等待、GET读回等待、恢复编辑及刷新历史',
  {concurrency: false, timeout: 240_000}, () => runScenario('normal'));
await test('服务收到POST前abort：无服务POST/新增修订，保留A并先读当前稿',
  {concurrency: false, timeout: 240_000}, () => runScenario('abort'));

