// Teacher execution: set DELIVERY_BROWSER_CHANNEL explicitly, then
// node --test scripts/test-saving.mjs (requires the existing dist; never builds).
// Run this same file/input at the restored historical point and frozen correct point.
// Historical red is an intentional comparison, not a newly found current-app defect.
import test from 'node:test';
import assert from 'node:assert/strict';
import {readFileSync, writeFileSync, mkdirSync} from 'node:fs';
import {resolve, dirname} from 'node:path';
import {fileURLToPath} from 'node:url';
import {randomUUID, createHash} from 'node:crypto';
import {execFileSync} from 'node:child_process';
import {devNull} from 'node:os';

const project = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const LIMIT = 12_000;
const ACTION_LIMIT = 4_000;
const sourcePaths = [
  'package.json', 'AGENTS.md', 'prototype/AGENTS.md', 'prototype/app.js',
  'prototype/index.html', 'src/prototype-http.ts', 'src/store.ts', 'src/schemas.ts',
  'scripts/seed.mjs', 'scripts/test-saving.mjs', 'docs/workbench-boundaries.md',
  'docs/save-review.md', 'inputs/完整教师初始化.json', 'inputs/独立业务预期.json',
  'inputs/输入冻结清单.json', 'inputs/青岚修仙录-三章原始课堂存档.md',
  'materials/historical/保存等待旧缺陷差异.patch',
  'materials/historical/保存等待历史行为.json',
  'materials/historical/历史真实Git差异来源.json',
  'dist/store.js', 'dist/schemas.js', 'dist/prototype-http.js',
];
const planned = {
  normal: ['initial', 'selected', 'before', 'comparison', 'gatesInstalled',
    'postWait', 'postKeyboard', 'getWait', 'getKeyboard', 'readback',
    'afterKeyboard', 'refresh'],
  abort: ['initial', 'selected', 'before', 'comparison', 'gatesInstalled',
    'aborted', 'failureLocal', 'recoveryRead', 'afterKeyboard'],
};
const now = () => new Date().toISOString();
const sha256 = bytes => createHash('sha256').update(bytes).digest('hex');
function errorRecord(error) {
  return {name: error?.name, message: String(error?.message ?? error),
    stack: error?.stack, code: error?.code, actual: error?.actual, expected: error?.expected};
}
function deferred() {
  let release;
  const promise = new Promise(resolvePromise => { release = resolvePromise; });
  return {promise, release};
}
async function bounded(promise, label, milliseconds = LIMIT) {
  let timer;
  try {
    return await Promise.race([promise, new Promise((_, reject) => {
      timer = setTimeout(() => reject(new Error(`${label}: exceeded ${milliseconds}ms`)), milliseconds);
    })]);
  } finally { clearTimeout(timer); }
}
function gitState() {
  const commands = [
    ['root', ['rev-parse', '--show-toplevel']], ['head', ['rev-parse', 'HEAD']],
    ['branch', ['branch', '--show-current']], ['version', ['--version']],
    ['status', ['status', '--porcelain=v1', '--untracked-files=all']],
    ['untracked', ['ls-files', '--others', '--exclude-standard']],
  ];
  return Object.fromEntries(commands.map(([name, args]) => {
    const command = ['--no-optional-locks', '-c', 'core.excludesFile=',
      '-c', 'core.fsmonitor=false', '-c', 'core.quotepath=false', ...args];
    try {
      const stdout = execFileSync('git', command, {cwd: project, encoding: 'utf8',
        timeout: LIMIT, windowsHide: true, maxBuffer: 8 * 1024 * 1024,
        env: {...process.env, GIT_CONFIG_NOSYSTEM: '1', GIT_CONFIG_GLOBAL: devNull},
        stdio: ['ignore', 'pipe', 'pipe']});
      return [name, {command, stdout}];
    } catch (error) {
      return [name, {command, error: errorRecord(error),
        stdout: String(error.stdout ?? ''), stderr: String(error.stderr ?? '')}];
    }
  }));
}
function readSources(report) {
  for (const path of sourcePaths) {
    try {
      const bytes = readFileSync(resolve(project, path));
      report.sources[path] = {path, bytes: bytes.length, sha256: sha256(bytes),
        utf8: bytes.toString('utf8'), base64: bytes.toString('base64')};
    } catch (error) {
      report.sources[path] = {path, error: errorRecord(error)};
      report.environmentErrors.push({path, error: errorRecord(error)});
    }
  }
  const lock = readFileSync(resolve(project, 'pnpm-lock.yaml'));
  report.environment.lock = {bytes: lock.length, sha256: sha256(lock)};
}
function instrumentServer(server, report) {
